def transform(grid):
    h, w = len(grid), len(grid[0])

    by_value = {}
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v != 0:
                if v not in by_value:
                    by_value[v] = []
                by_value[v].append((r, c))

    result = [[0] * w for _ in range(h)]

    for v, pos in by_value.items():
        for r, c in pos:
            result[r][c] = v

    for v, pos in by_value.items():
        pos_sorted = sorted(pos, key=lambda p: p[0])
        first_r, first_c = pos_sorted[0]
        last_r, last_c = pos_sorted[-1]
        min_c = min(p[1] for p in pos)
        max_c = max(p[1] for p in pos)

        if len(pos) == 1:
            for rr in range(first_r, h):
                result[rr][first_c] = v
        else:
            for rr in range(first_r, last_r + 1):
                result[rr][first_c] = v
            for cc in range(min_c, max_c + 1):
                result[last_r][cc] = v

    return result

